// Null tests of the FX module against golden renders made by Chromium itself
// (owner: fx; SPEC.md §11.7, §18.4): every FX type and every Color FX type,
// rendered by engine.js's own FxUnit in an OfflineAudioContext (reverbs with
// the seeded impulse handed to the ConvolverNode), except the feedback echoes,
// rendered by the same engine.js graphs with Chromium's one-quantum-per-trip
// feedback latency compensated (loop delay - 128 frames + 128 frames after
// the loop), since the native echoes are deliberately drift-free (§20).
// Generated by tests/fx/goldens/make_fx_goldens.js into
// $OM_GOLDEN_DIR/fx/: manifest.json, <case>.json (unit kind, rate, impulse,
// parameter events in frames), <case>.input.wav, <case>.wav. Each case is
// replayed through om::FxUnit / om::ColorFx with the same events at the same
// frames: residual < -80 dBFS. Skipped only when OM_GOLDEN_DIR is unset.
#include <cstdio>
#include <fstream>
#include <iterator>
#include <memory>
#include <string>
#include <vector>

#include "../om_test.h"
#include "fx_test_util.h"
#include "om/color_fx.h"
#include "om/convolver.h"
#include "om/fx.h"
#include "om/json.h"
#include "om/rt.h"

using namespace om;

namespace {

constexpr double kNullDb = -80.0;

bool readText(const std::string& path, std::string& out) {
  std::ifstream f(path, std::ios::binary);
  if (!f) return false;
  out.assign(std::istreambuf_iterator<char>(f), std::istreambuf_iterator<char>());
  return true;
}

// OM_FX_DUMP=<folder>: writes the native output of every case as
// <case>.native.wav (float32 stereo), to study a failing null test.
void dumpWav(const std::string& path, const std::vector<float>& l, const std::vector<float>& r, int rate) {
  std::ofstream f(path, std::ios::binary);
  if (!f) return;
  auto u32 = [&](uint32_t v) { f.write(reinterpret_cast<const char*>(&v), 4); };
  auto u16 = [&](uint16_t v) { f.write(reinterpret_cast<const char*>(&v), 2); };
  const uint32_t bytes = static_cast<uint32_t>(l.size() * 8);
  f.write("RIFF", 4);
  u32(36 + bytes);
  f.write("WAVEfmt ", 8);
  u32(16);
  u16(3);
  u16(2);
  u32(static_cast<uint32_t>(rate));
  u32(static_cast<uint32_t>(rate) * 8);
  u16(8);
  u16(32);
  f.write("data", 4);
  u32(bytes);
  for (size_t i = 0; i < l.size(); i++) {
    f.write(reinterpret_cast<const char*>(&l[i]), 4);
    f.write(reinterpret_cast<const char*>(&r[i]), 4);
  }
}

struct Event {
  int64_t frame;
  std::string op;
  json::Value value;
};

// Replays one case; returns the residual in dBFS (or +inf and a message on error).
double replay(const json::Value& c, const std::string& dir, std::string& why) {
  const std::string name = c["case"].asString();
  omtest::Wav in, gold;
  std::string err;
  if (!omtest::readWav(dir + c["input"].asString(), in, &err) || !omtest::readWav(dir + c["output"].asString(), gold, &err)) {
    why = err;
    return 1e9;
  }
  if (in.channels != 2 || gold.channels != 2 || in.frames() != gold.frames()) {
    why = "unexpected WAV layout";
    return 1e9;
  }
  const double sr = c["sampleRate"].asNumber(48000);
  const size_t frames = static_cast<size_t>(in.frames());
  std::vector<Event> events;
  for (const json::Value& e : c["events"].items())
    events.push_back({static_cast<int64_t>(e["frame"].asNumber(0)), e["op"].asString(), e["value"]});
  std::shared_ptr<const ConvolverKernel> kernel;
  const json::Value& imp = c["impulse"];
  if (imp.isObject()) {
    kernel = ConvolverKernel::build(makeImpulse(imp["seconds"].asNumber(2.2), imp["decay"].asNumber(2.5), static_cast<int>(sr),
                                                static_cast<uint32_t>(imp["seed"].asNumber(1))),
                                    kMaxBlockFrames);
  }
  const bool color = c["kind"].asString() == "color";
  FxUnit unit;
  ColorFx bus;
  if (color) {
    bus.prepare(sr, kMaxBlockFrames, kernel);
    for (int t = 0; t < kNumColorTypes; t++) {
      FxChainPtr ch = bus.makeChain(static_cast<ColorType>(t));
      if (ch && !bus.attachChain(static_cast<ColorType>(t), ch.get())) (void)ch.release();
    }
  } else {
    unit.prepare(sr, kMaxBlockFrames, kernel);
    for (int t = 0; t < kNumFxTypes; t++) {
      FxChainPtr ch = unit.makeChain(static_cast<FxType>(t));
      if (ch && !unit.attachChain(static_cast<FxType>(t), ch.get())) (void)ch.release();
    }
  }
  std::vector<float> l(frames), r(frames), ol(frames), orr(frames);
  for (size_t i = 0; i < frames; i++) {
    l[i] = in.samples[2 * i];
    r[i] = in.samples[2 * i + 1];
  }
  double beatDur = 0.5;  // engine.js FxUnit default
  size_t ev = 0;
  size_t pos = 0;
  while (pos < frames) {
    while (ev < events.size() && events[ev].frame <= static_cast<int64_t>(pos)) {
      const Event& e = events[ev++];
      if (color) {
        ColorType t;
        if (e.op == "colorType" && colorTypeFromName(e.value.asString().c_str(), t)) bus.setType(t);
        continue;
      }
      if (e.op == "setType") {
        FxType t;
        if (fxTypeFromName(e.value.asString().c_str(), t)) unit.setType(t);
      } else if (e.op == "setEnabled") {
        unit.setEnabled(e.value.asBool(false));
      } else if (e.op == "setLevel") {
        unit.setLevel(static_cast<float>(e.value.asNumber(0)));
      } else if (e.op == "setBeatsMult") {
        unit.setBeatsMult(static_cast<float>(e.value.asNumber(0.5)));
      } else if (e.op == "setBeatDur") {
        beatDur = e.value.asNumber(0.5);
        BeatClock bc;
        bc.beatDur = beatDur;
        unit.setBeatClock(bc);  // in event order, like engine.js setBeatDur
      }
    }
    size_t end = std::min(frames, pos + 128);
    if (ev < events.size()) end = std::min(end, static_cast<size_t>(std::max<int64_t>(events[ev].frame, static_cast<int64_t>(pos) + 1)));
    const int n = static_cast<int>(end - pos);
    rt::Scope rts;
    if (color) {
      bus.process(l.data() + pos, r.data() + pos, ol.data() + pos, orr.data() + pos, n);
    } else {
      BeatClock bc;
      bc.beatDur = beatDur;  // free-running: app.js setBeatDur only (no reference deck)
      unit.setBeatClock(bc);
      unit.process(l.data() + pos, r.data() + pos, ol.data() + pos, orr.data() + pos, n);
    }
    pos = end;
  }
  const std::string dump = omtest::envString("OM_FX_DUMP");
  if (!dump.empty()) dumpWav(dump + "/" + name + ".native.wav", ol, orr, static_cast<int>(sr));
  // First-repeat cases stop before Chromium's second repeat (its drift).
  const size_t compare = std::min(frames, static_cast<size_t>(c["compareFrames"].asNumber(static_cast<double>(frames))));
  double m = 0;
  size_t worstAt = 0;
  double peak = 0;
  for (size_t i = 0; i < compare; i++) {
    const double dl = std::fabs(static_cast<double>(ol[i]) - gold.samples[2 * i]);
    const double dr = std::fabs(static_cast<double>(orr[i]) - gold.samples[2 * i + 1]);
    peak = std::max({peak, std::fabs(static_cast<double>(gold.samples[2 * i])), std::fabs(static_cast<double>(gold.samples[2 * i + 1]))});
    if (std::max(dl, dr) > m) {
      m = std::max(dl, dr);
      worstAt = i;
    }
  }
  const double res = fxtest::db(m);
  std::printf("    %-26s %6.0f Hz  residual %7.1f dBFS (worst at %.4f s, golden peak %.3f)\n", name.c_str(), sr, res,
              worstAt / sr, peak);
  return res;
}

void runFamily(const char* family) {
  const std::string base = omtest::goldenPath("fx/");
  if (base.empty()) OM_SKIP("OM_GOLDEN_DIR is not set (run tests/fx/goldens/make_fx_goldens.js)");
  std::string text, err;
  if (!readText(base + "manifest.json", text)) omtest::fail("fx/manifest.json readable", __FILE__, __LINE__, base);
  json::Value manifest;
  if (!json::parse(text, manifest, &err)) omtest::fail("manifest parses", __FILE__, __LINE__, err);
  int cases = 0, failed = 0;
  for (const json::Value& nameV : manifest["cases"].items()) {
    const std::string name = nameV.asString();
    std::string ct;
    json::Value c;
    if (!readText(base + name + ".json", ct) || !json::parse(ct, c, &err)) {
      std::printf("    %s: unreadable case\n", name.c_str());
      failed++;
      continue;
    }
    if (c["family"].asString() != family) continue;
    cases++;
    std::string why;
    const double res = replay(c, base, why);
    if (!why.empty()) std::printf("    %s: %s\n", name.c_str(), why.c_str());
    if (!(res < kNullDb)) failed++;
  }
  if (cases == 0) omtest::fail("golden cases of this family present", __FILE__, __LINE__, family);
  if (failed) omtest::fail("every residual < -80 dBFS", __FILE__, __LINE__, std::to_string(failed) + " case(s) above");
}

}  // namespace

OM_TEST(fx_golden_delay_family) { runFamily("delay"); }
OM_TEST(fx_golden_modulation_family) { runFamily("modulation"); }
OM_TEST(fx_golden_reverb_crush_robot_roll) { runFamily("other"); }
OM_TEST(fx_golden_color_bus) { runFamily("color"); }
